/* BlackQuack — checkout con formulario de despacho.
   Sobrescribe el checkout() simulado de bq-v5.js. Cargar DESPUÉS de bq-v5.js.

   Manda SOLO {id, qty} + datos de despacho. El precio lo recalcula el servidor
   contra Contentful, y revalida todo esto en /api/checkout: lo de acá es UX,
   no seguridad. */
(function () {
  'use strict';

  var MODAL = 'shipModal';
  var regionesCache = null;

  /* Estado de la cotización de envío (Chilexpress, a domicilio). */
  var productsAmount = 0;   // total de productos (parseado del carrito)
  var shippingCost = null;  // costo de envío cotizado; null = aún no / sin cobertura
  var shipServiceName = ''; // "EXPRESS", "PRIORITARIO", ...
  var quoting = false;      // hay una cotización en curso

  function clp(n) { return '$' + Number(n || 0).toLocaleString('es-CL'); }

  function setFieldErr(name, msg) {
    var el = document.querySelector('#shipForm .err[data-for="' + name + '"]');
    if (!el) return;
    el.textContent = msg || '';
    var f = el.closest('.field');
    if (f) f.classList.toggle('has-err', !!msg);
  }

  function renderSummary() {
    var ship = document.getElementById('sumShip');
    if (!ship) return;
    document.getElementById('sumProducts').textContent = clp(productsAmount);
    document.getElementById('sumShipLabel').textContent =
      'Envío' + (shippingCost != null && shipServiceName ? ' · Chilexpress ' + shipServiceName : '');
    ship.textContent = quoting ? 'Calculando…' : (shippingCost == null ? 'Elige tu comuna' : clp(shippingCost));
    document.getElementById('sumTotal').textContent = clp(productsAmount + (shippingCost || 0));
  }

  /* Cotiza el envío a la comuna elegida y actualiza el resumen. El servidor
     REVALIDA esto en /api/checkout: acá es solo para mostrarle el costo al cliente. */
  async function requestQuote() {
    var sel = document.getElementById('sfComuna');
    var comuna = sel ? sel.value : '';
    setFieldErr('comuna', '');
    if (!comuna) { shippingCost = null; shipServiceName = ''; renderSummary(); return; }
    quoting = true; shippingCost = null; shipServiceName = ''; renderSummary();
    try {
      var res = await fetch('/api/shipping/quote', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ comuna: comuna, items: cartItems() })
      });
      var data = await res.json().catch(function () { return null; });
      quoting = false;
      if (data && data.ok) {
        shippingCost = data.costo; shipServiceName = data.servicio || '';
      } else {
        shippingCost = null; shipServiceName = '';
        setFieldErr('comuna', (data && data.error) || 'No pudimos calcular el envío.');
      }
      renderSummary();
    } catch (e) {
      quoting = false; shippingCost = null; shipServiceName = ''; renderSummary();
      setFieldErr('comuna', 'No pudimos calcular el envío. Reintenta.');
    }
  }

  /* ---------- utilidades de validación (espejo del servidor) ---------- */

  function cleanRut(rut) {
    return String(rut || '').toUpperCase().replace(/[^0-9K]/g, '');
  }

  function rutCheckDigit(body) {
    var sum = 0, mul = 2;
    for (var i = body.length - 1; i >= 0; i--) {
      sum += Number(body[i]) * mul;
      mul = mul === 7 ? 2 : mul + 1;
    }
    var rest = 11 - (sum % 11);
    return rest === 11 ? '0' : rest === 10 ? 'K' : String(rest);
  }

  function isValidRut(rut) {
    var c = cleanRut(rut);
    if (c.length < 8 || c.length > 9) return false;
    var body = c.slice(0, -1);
    if (!/^\d+$/.test(body)) return false;
    return rutCheckDigit(body) === c.slice(-1);
  }

  function formatRut(rut) {
    var c = cleanRut(rut);
    if (c.length < 2) return c;
    return c.slice(0, -1).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '-' + c.slice(-1);
  }

  function normalizePhone(v) {
    var d = String(v || '').replace(/[^\d]/g, '');
    if (d.indexOf('56') === 0) d = d.slice(2);
    return (d.length === 9 && d[0] === '9') ? '+56' + d : null;
  }

  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

  function validate(v) {
    var e = {};
    if (!v.nombre || v.nombre.trim().length < 5 || v.nombre.trim().indexOf(' ') === -1)
      e.nombre = 'Ingresa tu nombre y apellido.';
    if (!isValidRut(v.rut)) e.rut = 'RUT inválido. Revisa el dígito verificador.';
    if (!EMAIL_RE.test(v.email || '')) e.email = 'Email inválido.';
    if (!normalizePhone(v.telefono)) e.telefono = 'Móvil inválido (ej: 9 1234 5678).';
    if (!v.direccion || v.direccion.trim().length < 6) e.direccion = 'Ingresa calle y número.';
    else if (!/\d/.test(v.direccion)) e.direccion = 'La dirección debe incluir el número.';
    if (!v.comuna) e.comuna = 'Selecciona tu comuna.';
    return e;
  }

  /* ---------- render ---------- */

  var esc = function (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };

  function modalHTML(total) {
    return '<div class="modal" id="' + MODAL + '">' +
      '<div class="modal-bg" onclick="closeModal(\'' + MODAL + '\')"></div>' +
      '<div class="modal-card">' +
        '<div class="modal-top">' +
          '<div><h3>Datos de despacho</h3><div class="sub">Despacho a domicilio · Chilexpress</div></div>' +
          '<button class="modal-close" data-hover onclick="closeModal(\'' + MODAL + '\')"><i data-lucide="x"></i></button>' +
        '</div>' +
        '<div class="modal-body">' +
          '<div class="ship-note">' +
            '<i data-lucide="truck"></i>' +
            '<div>El <strong>envío a domicilio</strong> se calcula con Chilexpress según tu comuna. ' +
            'Elígela y verás el costo abajo antes de pagar.</div>' +
          '</div>' +
          '<form id="shipForm" novalidate>' +
            /* --- Orden UX: contacto primero, luego dirección (de lo amplio a lo específico) --- */
            '<p class="field-section">Tus datos</p>' +
            '<div class="field"><label for="sfEmail">Email *</label>' +
              '<input id="sfEmail" name="email" type="email" autocomplete="email" inputmode="email" placeholder="tu@email.com"><small class="err" data-for="email"></small></div>' +
            '<div class="field"><label for="sfNombre">Nombre completo *</label>' +
              '<input id="sfNombre" name="nombre" type="text" autocomplete="name" placeholder="Paulo Correa"><small class="err" data-for="nombre"></small></div>' +
            '<div class="field-row">' +
              '<div class="field"><label for="sfRut">RUT *</label>' +
                '<input id="sfRut" name="rut" type="text" inputmode="text" autocomplete="off" placeholder="12.345.678-5"><small class="err" data-for="rut"></small></div>' +
              '<div class="field"><label for="sfTel">Teléfono *</label>' +
                '<input id="sfTel" name="telefono" type="tel" autocomplete="tel" inputmode="tel" placeholder="9 1234 5678"><small class="err" data-for="telefono"></small></div>' +
            '</div>' +
            '<p class="field-section">Dirección de entrega</p>' +
            '<div class="field-row">' +
              '<div class="field"><label for="sfRegion">Región *</label>' +
                '<select id="sfRegion" name="region"><option value="">Cargando…</option></select></div>' +
              '<div class="field"><label for="sfComuna">Comuna *</label>' +
                '<select id="sfComuna" name="comuna" disabled><option value="">Elige región primero</option></select>' +
                '<small class="err" data-for="comuna"></small></div>' +
            '</div>' +
            '<div class="field"><label for="sfDir">Dirección — calle y número *</label>' +
              '<input id="sfDir" name="direccion" type="text" autocomplete="street-address" placeholder="Av. Los Carrera 1234, depto 5B"><small class="err" data-for="direccion"></small></div>' +
            '<div class="field"><label for="sfRef">Referencia <span style="font-weight:400;opacity:.6">(opcional)</span></label>' +
              '<input id="sfRef" name="referencia" type="text" placeholder="Portón negro, entre calles X e Y"></div>' +
            '<div class="ship-summary" id="shipSummary" style="margin:14px 0">' +
              '<div class="ship-row" style="display:flex;justify-content:space-between;padding:4px 0">' +
                '<span>Productos</span><span id="sumProducts">' + esc(clp(productsAmount)) + '</span></div>' +
              '<div class="ship-row" style="display:flex;justify-content:space-between;padding:4px 0">' +
                '<span id="sumShipLabel">Envío</span><span id="sumShip">Elige tu comuna</span></div>' +
              '<div class="ship-row ship-total" style="display:flex;justify-content:space-between;padding:8px 0;margin-top:4px;border-top:1px solid currentColor;font-weight:700">' +
                '<span>Total</span><span id="sumTotal">' + esc(clp(productsAmount)) + '</span></div>' +
            '</div>' +
            '<small class="err" data-for="_form" style="display:block;margin-bottom:10px"></small>' +
            '<button type="submit" class="cta-brutal" id="sfSubmit" data-hover style="margin-top:4px">' +
              '<i data-lucide="credit-card"></i> Ir a pagar con Flow</button>' +
            '<p class="ship-legal">Al continuar te redirigimos a Flow para completar el pago de forma segura. ' +
            'Usamos tu RUT y teléfono solo para emitir la boleta y para coordinar la entrega con el courier.</p>' +
          '</form>' +
        '</div>' +
      '</div>' +
    '</div>';
  }

  function showErrors(errs) {
    document.querySelectorAll('#shipForm .err').forEach(function (el) {
      var k = el.dataset.for;
      el.textContent = errs[k] || '';
      var field = el.closest('.field');
      if (field) field.classList.toggle('has-err', !!errs[k]);
    });
    var first = document.querySelector('#shipForm .field.has-err input, #shipForm .field.has-err select');
    if (!first) return;
    /* El scroll automático del focus deja el campo debajo del .modal-top sticky,
       tapando su etiqueta. Centramos el campo nosotros. */
    first.focus({ preventScroll: true });
    first.scrollIntoView({ block: 'center', behavior: 'smooth' });
  }

  function readForm() {
    var f = document.getElementById('shipForm');
    var get = function (n) { return (f.elements[n] && f.elements[n].value || '').trim(); };
    return {
      nombre: get('nombre'), rut: get('rut'), email: get('email'), telefono: get('telefono'),
      direccion: get('direccion'), comuna: get('comuna'), region: get('region'), referencia: get('referencia')
    };
  }

  /* ---------- regiones / comunas ---------- */

  async function loadRegiones() {
    if (regionesCache) return regionesCache;
    // Fuente principal: el endpoint (misma lista que valida el servidor).
    try {
      var res = await fetch('/api/comunas');
      if (res.ok) {
        var data = await res.json();
        if (Array.isArray(data) && data.length) { regionesCache = data; return regionesCache; }
      }
    } catch (e) { /* cae al fallback embebido */ }
    // Fallback: dataset embebido — funciona sin el endpoint (archivo local, etc.).
    if (window.BQ_COMUNAS_FALLBACK && window.BQ_COMUNAS_FALLBACK.length) {
      regionesCache = window.BQ_COMUNAS_FALLBACK;
      return regionesCache;
    }
    throw new Error('No pudimos cargar las comunas.');
  }

  function fillRegiones(regiones) {
    var rSel = document.getElementById('sfRegion');
    var cSel = document.getElementById('sfComuna');
    rSel.innerHTML = '<option value="">Selecciona…</option>' +
      regiones.map(function (r, i) { return '<option value="' + i + '">' + esc(r.region) + '</option>'; }).join('');

    rSel.addEventListener('change', function () {
      var r = regiones[rSel.value];
      if (!r) {
        cSel.innerHTML = '<option value="">Elige región primero</option>';
        cSel.disabled = true;
        return;
      }
      cSel.innerHTML = '<option value="">Selecciona…</option>' +
        r.comunas.map(function (c) { return '<option value="' + esc(c) + '">' + esc(c) + '</option>'; }).join('');
      cSel.disabled = false;
    });
  }

  /* ---------- flujo ---------- */

  function cartItems() {
    // El carrito está indexado por SKU; cada línea lleva id + atributos de variante.
    return Object.keys(cart).map(function (sku) {
      var l = cart[sku];
      return { id: l.id, size: l.size || '', color: l.color || '', design: l.design || '', qty: l.qty };
    });
  }

  async function submitForm(ev) {
    ev.preventDefault();
    var v = readForm();
    var errs = validate(v);
    if (Object.keys(errs).length) return showErrors(errs);
    showErrors({});

    // El envío debe estar cotizado antes de pagar (así el total mostrado es real).
    if (quoting) { setFieldErr('_form', 'Estamos calculando el envío, espera un segundo…'); return; }
    if (shippingCost == null) {
      setFieldErr('comuna', 'Elige una comuna con cobertura para calcular el envío.');
      return;
    }

    var btn = document.getElementById('sfSubmit');
    var original = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = 'Conectando con Flow…';

    try {
      var res = await fetch('/api/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: v.email,
          items: cartItems(),
          shipping: {
            nombre: v.nombre, rut: v.rut, telefono: v.telefono,
            direccion: v.direccion, comuna: v.comuna, referencia: v.referencia
          }
        })
      });
      /* La respuesta puede NO ser JSON: ante un 5xx, Cloudflare reemplaza el
         cuerpo por su propia página de error HTML. Parseamos a prueba de fallos
         para nunca mostrarle al cliente un "Unexpected token '<'". */
      var data = await res.json().catch(function () { return null; });

      if (!res.ok || !data || !data.redirect) {
        /* El servidor puede rechazar campos que el cliente dejó pasar
           (comuna inexistente, stock que se acabó recién). Los mostramos ahí mismo. */
        if (data && data.fields) showErrors(data.fields);
        var msg = (data && data.error)
          || (res.status >= 500
                ? 'No pudimos iniciar el pago en este momento. Intenta nuevamente en unos segundos.'
                : 'No pudimos iniciar el pago.');
        throw new Error(msg);
      }

      // El carrito se vacía solo en gracias.html con status=paid.
      location.href = data.redirect;
    } catch (e) {
      var box = document.querySelector('#shipForm .err[data-for="_form"]');
      if (box) box.textContent = e.message;
      btn.disabled = false;
      btn.innerHTML = original;
      if (window.lucide) lucide.createIcons();
    }
  }

  async function startCheckout() {
    if (!Object.keys(cart).length) return;

    var total = document.getElementById('total');
    productsAmount = parseInt(String(total ? total.textContent : '').replace(/[^\d]/g, ''), 10) || 0;
    shippingCost = null; shipServiceName = ''; quoting = false;
    var old = document.getElementById(MODAL);
    if (old) old.remove();
    document.body.insertAdjacentHTML('beforeend', modalHTML(total ? total.textContent : ''));

    if (typeof closeCartFn === 'function') closeCartFn();
    openModal(MODAL);
    document.getElementById('shipForm').addEventListener('submit', submitForm);

    // Formatea el RUT al salir del campo, para que se guarde consistente.
    var rutEl = document.getElementById('sfRut');
    rutEl.addEventListener('blur', function () {
      if (rutEl.value.trim()) rutEl.value = formatRut(rutEl.value);
    });

    try {
      fillRegiones(await loadRegiones());
    } catch (e) {
      document.getElementById('sfRegion').innerHTML = '<option value="">Error al cargar</option>';
      var box = document.querySelector('#shipForm .err[data-for="_form"]');
      if (box) box.textContent = 'No pudimos cargar las comunas. Recarga la página.';
    }

    // Al elegir comuna, cotizamos el envío con Chilexpress y actualizamos el total.
    var comunaSel = document.getElementById('sfComuna');
    if (comunaSel) comunaSel.addEventListener('change', requestQuote);
    renderSummary();

    if (window.lucide) lucide.createIcons();
  }

  window.checkout = startCheckout;
})();
